def strategy(history, rng):
    n = len(history)
    if n < 10:
        return 'C'
    if n == 10:
        return 'D'
    if n == 11:
        return 'C'
    my = [h[0] for h in history]
    opp = [h[1] for h in history]
    tolerant = (opp[11] == 'C')
    if tolerant:
        for i in range(12, n):
            if my[i] == 'C' and opp[i] == 'D':
                tolerant = False
                break
        if tolerant:
            opp_d = sum(1 for a in opp if a == 'D')
            if opp_d > 0 and opp_d / n > 0.1:
                tolerant = False
    if tolerant:
        if n >= 98:
            return 'D'
        if (n + 1) % 5 == 0:
            return 'D'
        return 'C'
    else:
        if n >= 98:
            return 'D'
        recent_opp_d = sum(1 for i in range(max(0, n-10), n) if opp[i] == 'D')
        if recent_opp_d >= 6:
            return 'D'
        if opp[-1] == 'D':
            if my[-1] == 'D':
                return 'C' if rng.random() < 0.2 else 'D'
            return 'C'
        return 'C'
